import{_ as r,a0 as a,w as p,s as d,ao as s,I as t,x as e,a1 as o,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在基於RedHat與Debian的系統上安裝Wine 最新的開發版本 | LCTT x X-CMD","titleTemplate":false,"description":"在基於RedHat與Debian的系統上安裝Wine 最新的開發版本 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在基於RedHat與Debian的系統上安裝Wine 最新的開發版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在基於RedHat與Debian的系統上安裝Wine 最新的開發版本 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/Wine 1.7.29 (Development Version) Released – Install in RedHat and Debian Based Systems","title":"在基於RedHat與Debian的系統上安裝Wine 最新的開發版本","tag":"201410","desc":""},"relativePath":"201410/Wine 1.7.29 (Development Version) Released – Install in RedHat and Debian Based Systems.md","filePath":"[post].md"}'),u={name:"201410/Wine 1.7.29 (Development Version) Released – Install in RedHat and Debian Based Systems.md"};function m(g,n,w,b,f,W){const i=a("Link");return p(),d("div",null,[n[19]||(n[19]=s('<h1 id="在基於redhat與debian的系統上安裝wine-最新的開發版本" tabindex="-1">在基於RedHat與Debian的系統上安裝Wine 最新的開發版本 <a class="header-anchor" href="#在基於redhat與debian的系統上安裝wine-最新的開發版本" aria-label="Permalink to “在基於RedHat與Debian的系統上安裝Wine 最新的開發版本”">​</a></h1><p><strong>Wine</strong>,一個在Linux平台上非常受歡迎並且強大的開源應用，有了它，我們可以在Linux平台上完美運行Windows應用與遊戲。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/05/Install-Wine-Development-Version.png" alt="Install Wine (Development Version) in Linux"></p><p><em>在Linux上安裝Wine（開發版本）</em></p><p>WineHQ團隊，近期宣佈了一個新的開發版本<strong>Wine1.7.29</strong>。這個版本帶來了諸多重要的特性，並且修復了<strong>44</strong>個bug。</p><p>Wine團隊幾乎每週都會發布新的開發版本，並且加入許多新特性以及修復漏洞。每個新版本都會支持新的應用與遊戲（Windows），這使得Wine在那些想要在Linux下運行Windows應用的用户羣體中很流行並且是不可缺少的。</p><p>根據變更日誌，這個版本中添加了以下的關鍵特性：</p><ul><li>在DirectWrite中加入增強的外形塑造與BiDi（譯者：bi-directional language）鏡像。</li><li>升級了一些頁面錯誤處理方式。</li><li>增加了更多的C運行時函數。</li><li>修復了大量的bug。</li></ul>',8)),t("p",null,[n[1]||(n[1]=e("在官方的 ",-1)),o(i,{href:"http://www.winehq.org/announce/1.7.29"},{default:l(()=>[...n[0]||(n[0]=[e("變更日誌",-1)])]),_:1}),n[2]||(n[2]=e(" 中可以找到關於這個版本更多更深入的細節。",-1))]),n[20]||(n[20]=s(`<p>這篇文章指導你在基於<strong>RedHat</strong>與<strong>Debian</strong>的系統，如CentOS，Fedora，Ubuntu，Linux Mint以及其他的發行版中安裝最新的開發版本<strong>Wine 1.7.29</strong>。</p><p>##在Linux中安裝 Wine 1.7.29 開發版本##</p><p>遺憾的是，目前還沒有官方的Wine倉庫可以獲取基於<strong>RedHat</strong>系統的版本，只能通過編譯源碼來安裝。如果要這麼做的話，我們先要安裝一些開發包如gcc，flex，bison，libX11-devel freetype-devel　以及開發工具，等等。這些工具都是編譯Wine源碼所必須的。我們可以通過<strong>YUM</strong>命令來安裝這些包。</p><p>##RedHat，Fedora，CentOS##</p><pre><code># yum -y groupinstall &#39;Development Tools&#39;
# yum -y install flex bison libX11-devel freetype-devel
</code></pre><p>然後，使用如下命令下載Wine最新的開發版本（<strong>1.7.29</strong>）以及解壓源碼包。</p><pre><code>$ cd /tmp
$ wget http://citylan.dl.sourceforge.net/project/wine/Source/wine-1.7.29.tar.bz2
$ tar -xvf wine-1.7.29.tar.bz2 -C /tmp/
</code></pre><p>接下來，使用下列命令編譯及安裝Wine。</p><p>注：安裝過程大概需要<strong>15-20</strong>分鐘，這個時間由你的網絡速度以及電腦硬件配置決定，在安裝過程中需要<strong>root</strong>密碼。</p><p>####32位系統####</p><pre><code>$cd wine-1.7.29/
$./tools/wineinstall
</code></pre><p>####64位系統####</p><pre><code>$ cd wine-1.7.29/
$ ./configure --enable-win64
$ make
# make install
</code></pre><p>###Ubuntu，Debian 與 Linux Mint###</p><p>在<strong>Ubuntu</strong>系統下，你可以使用官方的<strong>PPA</strong>方便的安裝最新的Wine開發版本。打開一個終端並使用sudo權限執行下列命令。</p><pre><code>$ sudo add-apt-repository ppa:ubuntu-wine/ppa 
$ sudo apt-get update
$ sudo apt-get install wine 1.7 winetricks
</code></pre><p><strong>注</strong>：在寫這篇文章時，只能獲取<strong>1.7.26</strong>，在官方的倉庫中還沒有更新到最新版本，但是當倉庫更新到<strong>1.7.29</strong>後，使用上面的指令可以安裝最新的版本。（譯者：為毛我看了版本號是1.6.2......）</p><p>安裝成功後，你可以安裝或運行任何windows應用或遊戲了，示例如下：</p><pre><code>$ wine notepad
$ wine notepad.exe 
$ wine c:\\\\windows\\\\notepad.exe
</code></pre><p><strong>注</strong>：切記，這是一個開發版本，請勿在生產系統上安裝它。建議這個版本僅作測試用。</p><p>如果你需要最新的穩定版本，可以參考下列文章，它介紹瞭如何安裝最新的穩定版本。</p>`,21)),t("ul",null,[t("li",null,[o(i,{href:"http://www.tecmint.com/install-wine-in-rhel-centos-and-fedora/"},{default:l(()=>[...n[3]||(n[3]=[e("Install Wine 1.6.2 (Stable) in RHEL, CentOS and Fedora",-1)])]),_:1})]),t("li",null,[o(i,{href:"http://www.tecmint.com/install-wine-on-ubuntu-and-linux-mint/"},{default:l(()=>[...n[4]||(n[4]=[e("Install Wine 1.6.2 (Stable) in Debian, Ubuntu and Mint",-1)])]),_:1})])]),n[21]||(n[21]=t("p",null,"###參考鏈接###",-1)),t("ul",null,[t("li",null,[o(i,{href:"http://www.winehq.org/"},{default:l(()=>[...n[5]||(n[5]=[e("WineHQ Homepage",-1)])]),_:1})])]),n[22]||(n[22]=t("hr",null,null,-1)),t("p",null,[n[7]||(n[7]=e("via: ",-1)),o(i,{href:"http://www.tecmint.com/install-wine-in-linux/"},{default:l(()=>[...n[6]||(n[6]=[e("http://www.tecmint.com/install-wine-in-linux/",-1)])]),_:1})]),t("p",null,[n[11]||(n[11]=e("作者：",-1)),o(i,{href:"http://www.tecmint.com/author/admin/"},{default:l(()=>[...n[8]||(n[8]=[e("Ravi Saive",-1)])]),_:1}),n[12]||(n[12]=e(" 譯者：",-1)),o(i,{href:"https://github.com/SPccman"},{default:l(()=>[...n[9]||(n[9]=[e("SPccman",-1)])]),_:1}),n[13]||(n[13]=e(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:l(()=>[...n[10]||(n[10]=[e("wxy",-1)])]),_:1})]),t("p",null,[n[16]||(n[16]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[14]||(n[14]=[e("LCTT",-1)])]),_:1}),n[17]||(n[17]=e(" 原創翻譯，",-1)),o(i,{href:"http://linux.cn/"},{default:l(()=>[...n[15]||(n[15]=[e("Linux中國",-1)])]),_:1}),n[18]||(n[18]=e(" 榮譽推出",-1))])])}const C=r(u,[["render",m]]);export{T as __pageData,C as default};
